--
-- Table structure for table `course_section_content`
--

DROP TABLE IF EXISTS `course_section_content`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `course_section_content` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `course_id` bigint unsigned NOT NULL COMMENT '课程ID',
  `chapter_id` bigint unsigned NOT NULL COMMENT '章节ID',
  `section_id` bigint unsigned NOT NULL COMMENT '小节ID',
  `title` varchar(200) NOT NULL COMMENT '内容项标题',
  `content_type` varchar(20) NOT NULL COMMENT '内容类型: VIDEO/RICH_TEXT/PDF/FILE',
  `content_html` longtext COMMENT '富文本HTML内容',
  `content_json` longtext COMMENT '富文本结构化JSON内容',
  `file_url` varchar(255) DEFAULT NULL COMMENT '文件或视频地址',
  `object_key` varchar(500) DEFAULT NULL COMMENT 'OSS对象Key',
  `file_name` varchar(255) DEFAULT NULL COMMENT '原始文件名',
  `mime_type` varchar(100) DEFAULT NULL COMMENT '文件MIME类型',
  `file_size` bigint unsigned NOT NULL DEFAULT '0' COMMENT '文件大小，字节',
  `duration` int NOT NULL DEFAULT '0' COMMENT '视频时长，单位秒',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序值',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态: 0禁用 1启用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` bigint unsigned DEFAULT '0' COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT '0' COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_course_section_content_section` (`section_id`),
  KEY `idx_course_section_content_course` (`course_id`),
  KEY `idx_course_section_content_chapter` (`chapter_id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='课程小节内容项表';
/*!40101 SET character_set_client = @saved_cs_client */;

