DROP TABLE IF EXISTS `exam_submission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exam_submission` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `task_id` bigint unsigned NOT NULL,
  `member_id` bigint unsigned NOT NULL,
  `attempt_no` int NOT NULL DEFAULT '1',
  `answers_json` json DEFAULT NULL,
  `attachment_url` varchar(255) DEFAULT NULL,
  `objective_score` int NOT NULL DEFAULT '0',
  `subjective_score` int NOT NULL DEFAULT '0',
  `score` int NOT NULL DEFAULT '0',
  `review_status` tinyint NOT NULL DEFAULT '0',
  `review_comment` varchar(500) DEFAULT NULL,
  `submitted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint unsigned DEFAULT '0',
  `updated_by` bigint unsigned DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_exam_submission_task_id` (`task_id`),
  KEY `idx_exam_submission_member_id` (`member_id`),
  KEY `idx_exam_submission_review_status` (`review_status`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
